/**
 * Send a test notification through a channel. Test Notifications are
 * clearly separate from business Incidents (event kind `test`), always
 * produce an Audit Event, and send synchronously so the response carries
 * the resulting Delivery state. Provider tokens never enter the request,
 * response, Audit body, or logs.
 */
export const testNotificationChannel = <ThrowOnError extends boolean = false>(options: Options<TestNotificationChannelData, ThrowOnError>): RequestResult<TestNotificationChannelResponses, TestNotificationChannelErrors, ThrowOnError> => (options.client ?? client).post<TestNotificationChannelResponses, TestNotificationChannelErrors, ThrowOnError>({ url: '/api/admin/v1/notifications/channels/{channel_id}/test', ...options });

